 34	    this.dispatch = dispatch
 35	    this.location = null
 36	    this.abort = null
 37	    this.opts = { ...opts, maxRedirections: 0 } // opts must be a copy
 38	    this.maxRedirections = maxRedirections
 39	    this.handler = handler
 40	    this.history = []
 41	    this.redirectionLimitReached = false
 42	
 43	    if (util.isStream(this.opts.body)) {
 44	      // TODO (fix): Provide some way for the user to cache the file to e.g. /tmp
 45	      // so that it can be dispatched again?
 46	      // TODO (fix): Do we need 100-expect support to provide a way to do this properly?
