207	  }
208	  return false
209	}
210	
211	// https://tools.ietf.org/html/rfc7231#section-6.4
212	function cleanRequestHeaders (headers, removeContent, unknownOrigin) {
213	  const ret = []
214	  if (Array.isArray(headers)) {
