216	      if (!shouldRemoveHeader(headers[i], removeContent, unknownOrigin)) {
217	        ret.push(headers[i], headers[i + 1])
218	      }
219	    }
220	  } else if (headers && typeof headers === 'object') {
221	    for (const key of Object.keys(headers)) {
222	      if (!shouldRemoveHeader(key, removeContent, unknownOrigin)) {
223	        ret.push(key, headers[key])
224	      }
225	    }
226	  } else {
227	    assert(headers == null, 'headers must be an object or an array')
228	  }
229	  return ret
230	}
231	
232	module.exports = RedirectHandler

