input.command:
node -e "
const f = JSON.parse(require('node:fs').readFileSync('findings.json','utf8'));
const keys = ['file','function','line_start','line_end','cwe','title','explanation'];
for (const x of f.findings) {
  for (const k of keys) if (!(k in x)) throw new Error('missing '+k);
  if (!require('node:fs').existsSync(x.file)) throw new Error('bad file '+x.file);
  for (const s of x.path ?? []) { if (!require('node:fs').existsSync(s.file)) throw new Error('bad path file '+s.file) }
  console.log(x.cwe, x.file+':'+x.line_start+'-'+x.line_end, '|', x.title);
}
console.log('findings:', f.findings.length, '| valid JSON, shape ok');
" && ls -la findings.json && echo "--- confirm no other files changed ---" && find . -maxdepth 1 -newermt "2026-01-01" -type f

